#!ibl edition=2
$orders=filter($sources,($s)=>contains($s.name,"orders_"));
$failures=map(filter($orders,($s)=>not $s.ok),($s)=>{path:$s.path,reason:$s.reason});
$good=filter($orders,($s)=>$s.ok);
$parents=$good >> [table:each]{mode:"flat_map"}{return $it.data.items};
$safe=$parents >> [table:compute]{set:($p)=>{lines:map($p.lines,($l)=>{line_no:text($l.line_no),sku:$l.sku,qty:number($l.qty),note:$l.note,vendor_order_id:get($l,"order_id",null)})}};
$flat=$safe >> [table:flatten]{field:"lines",keep:["order_id","region"]};
$unique=$flat.items >> [table:dedup]{by:["order_id","line_no"]};
$price_source=filter($sources,($s)=>$s.name=="prices.csv")[0];
$return_source=filter($sources,($s)=>$s.name=="returns.csv")[0];
assert $price_source.ok and $return_source.ok,"단가 또는 반품 원천 읽기 실패";
$prices=$price_source.data.items >> [table:select]{columns:["sku","unit_price"]} >> [table:compute]{set:($r)=>{unit_price:number($r.unit_price)}};
$price_keys=$prices >> [table:dedup]{by:"sku"};
assert len($price_keys.items)==len($prices),"단가 SKU 중복";
$returns=$return_source.data.items >> [table:compute]{set:($r)=>{line_no:text($r.line_no),returned_qty:number($r.returned_qty)}} >> [table:groupby]{by:["order_id","line_no"],agg:{returned_qty:["sum","returned_qty"]}};
$with_returns=[table:join]{left:$unique.items,right:$returns.items,on:["order_id","line_no"],how:"left",defaults:{returned_qty:0}};
$joined=[table:join]{left:$with_returns.items,right:$prices,on:"sku",how:"left",defaults:{unit_price:null}};
assert len($joined.items)==len($unique.items),"결합 후 행수 변경";
$details=$joined.items >> [table:compute]{set:($r)=>{net_qty:$r.qty-$r.returned_qty,status:$r.returned_qty>$r.qty ? "excess_return" : $r.unit_price==null ? "unknown_price" : "ok"}} >> [table:compute]{set:($r)=>{amount:$r.status=="ok" ? $r.net_qty*$r.unit_price : null}} >> [table:compute]{set:($r)=>{eligible:$r.status=="ok" and $r.amount>=30000}} >> [table:select]{columns:$columns};
$metrics=$details >> [table:compute]{set:($r)=>{anomaly_flag:$r.status=="ok" ? 0 : 1,eligible_flag:$r.eligible ? 1 : 0}};
$groups=$metrics >> [table:groupby]{by:"region",agg:{lines:["count"],amount:["sum","amount"],anomalies:["sum","anomaly_flag"],eligible:["sum","eligible_flag"]}};
$regions=$groups.items >> [table:compute]{set:($r)=>{amount:$r.amount==null ? 0 : $r.amount}} >> [table:sort]{by:"region"};
$summary={regions:$regions,count:len($details),total_amount:sum(map($regions,($r)=>$r.amount)),threshold:30000,source_complete:len($failures)==0,failures:$failures,anomalies:sum(map($regions,($r)=>$r.anomalies)),eligible:sum(map($regions,($r)=>$r.eligible)),source_file_order:map($orders,($r)=>$r.path),ordering:"파일명 오름차순, 파일 내 주문·품목 순서; 복합키 최초 접수 유지",csv_serialization:{null:"empty cell",boolean:"true/false (case-insensitive on read)",note:"원문 보존, CSV 표준 인용"}};
return {details:$details,summary:$summary,audit:{order_files:len($orders),readable_order_files:len($good),parents:len($parents),flattened:len($flat.items),duplicates_removed:len($flat.items)-len($details),return_rows:len($return_source.data.items),return_keys:len($returns.items),prices:len($prices)}}

#!ibl edition=2
$raw=filter($sources,($s)=>contains($s.name,"orders_") and $s.ok) >> [table:each]{mode:"flat_map"}{ $it.data.items >> [table:each]{mode:"flat_map"}{ $p=$it; return map($p.lines,($l)=>{order_id:$p.order_id,line_no:text($l.line_no),region:$p.region,sku:$l.sku,qty:number($l.qty),note:$l.note,vendor_order_id:get($l,"order_id",null)}) } };
$ordered=sorted($raw,($r)=>json([$r.order_id,$r.line_no]));
$first=$ordered >> [table:each]{mode:"flat_map"}{ [if:$i==0 or $it.order_id!=$ordered[$i-1].order_id or $it.line_no!=$ordered[$i-1].line_no]{return [$it]}[else]{return []} };
$actual=sorted($result.details,($r)=>json([$r.order_id,$r.line_no]));
$lineage=$actual >> [table:select]{columns:["order_id","line_no","region","sku","qty","note","vendor_order_id"]};
assert $lineage==$first,"최초 원천행·부모 키·판매자 키·note 대조 불일치";
$ret_src=filter($sources,($s)=>$s.name=="returns.csv")[0].data.items;
$ret=sorted($ret_src,($r)=>json([$r.order_id,text($r.line_no)]));
$ret_reference=[]; $running=0;
[repeat:while $i<len($ret)]{
 $r=$ret[$i]; $running=$running+number($r.returned_qty);
 [if:$i==len($ret)-1 or $r.order_id!=$ret[$i+1].order_id or $r.line_no!=$ret[$i+1].line_no]{ $ret_reference=$ret_reference+[{order_id:$r.order_id,line_no:text($r.line_no),returned_qty:$running}]; $running=0 }
}
$price_src=filter($sources,($s)=>$s.name=="prices.csv")[0].data.items;
$price_reference=map($price_src,($r)=>{sku:$r.sku,unit_price:number($r.unit_price)});
$ref_returns=[table:join]{left:$first,right:$ret_reference,on:["order_id","line_no"],how:"left",defaults:{returned_qty:0}};
$ref_full=[table:join]{left:$ref_returns.items,right:$price_reference,on:"sku",how:"left",defaults:{unit_price:null}};
$checked=$ref_full.items >> [table:each]{
 $r=$it; $got=$actual[$i]; $net=$r.qty-$r.returned_qty;
 $status=$net<0 ? "excess_return" : $r.unit_price==null ? "unknown_price" : "ok";
 $amount=$status=="ok" ? $net*$r.unit_price : null;
 assert $got.returned_qty==$r.returned_qty and $got.unit_price==$r.unit_price and $got.net_qty==$net and $got.status==$status and $got.amount==$amount and $got.eligible==($status=="ok" and $amount>=30000),"정산 원천 대조 불일치",{order_id:$r.order_id,line_no:$r.line_no};
 assert keys($got)==$columns,"상세 필드 불일치";
 return true
};
$region_checks=$result.summary.regions >> [table:each]{
 $region=$it; $rows=filter($result.details,($r)=>$r.region==$region.region);
 $ok=filter($rows,($r)=>$r.status=="ok");
 assert $region.lines==len($rows) and $region.amount==sum(map($ok,($r)=>$r.amount)) and $region.anomalies==len($rows)-len($ok) and $region.eligible==len(filter($rows,($r)=>$r.eligible)),"지역 요약 불일치";
 return true
};
assert $result.summary.count==len($actual) and $result.summary.total_amount==sum(map(filter($actual,($r)=>$r.status=="ok"),($r)=>$r.amount)),"전체 합계 불일치";
$writes=[self:write]{path:f"${out}/details.json",content:json($result.details)} & [self:write]{path:f"${out}/details.csv",content:$result.details,format:"csv",columns:$columns} & [self:write]{path:f"${out}/summary.json",content:json($result.summary)};
$readback=[self:read]{path:f"${out}/details.json"} & [self:read]{path:f"${out}/details.csv"} & [self:read]{path:f"${out}/summary.json"};
assert $readback[0].data.items==$result.details,"저장 JSON 불일치";
assert $readback[2].data==$result.summary,"저장 요약 불일치";
assert $readback[1].data.table.columns==$columns,"CSV 열 불일치";
$csv=map($readback[1].data.items,($r)=>{order_id:$r.order_id,line_no:$r.line_no,region:$r.region,sku:$r.sku,qty:number($r.qty),returned_qty:number($r.returned_qty),unit_price:$r.unit_price=="" ? null : number($r.unit_price),net_qty:number($r.net_qty),amount:$r.amount=="" ? null : number($r.amount),status:$r.status,eligible:lower($r.eligible)=="true",note:$r.note,vendor_order_id:$r.vendor_order_id=="" ? null : $r.vendor_order_id});
assert $csv==$result.details,"CSV 재읽기 값·note 불일치";
assert all(map($readback[1].data.items,($r)=>lower($r.eligible) in ["true","false"])),"CSV 불리언 불일치";
return {verified:true,checked_rows:len($checked),checked_regions:len($region_checks),source_complete:$result.summary.source_complete,summary:$result.summary,audit:$result.audit,files:$writes}

